import React, { useState, useEffect } from 'react';
import styles from '../styles/AuthPage.module.css';

const AuthPage = ({ onLoginSuccess }) => {
  const [isSignUp, setIsSignUp] = useState(false);
  const [userType, setUserType] = useState(null); 
  const [businesses, setBusinesses] = useState([]); 
  const [selectedBusinessId, setSelectedBusinessId] = useState(null);
  const [loadingBusinesses, setLoadingBusinesses] = useState(false);

  const [formData, setFormData] = useState({
    email: '',
    password: '',
    first_name: '',
    last_name: '',
    phone: '',
    street: '',
    building_number: '',
    apartment_number: '',
    zip_code: '',
    city: '',
    state: '',
    country: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');

  const REACT_APP_API_BASE_URL = process.env.REACT_APP_API_BASE_URL;
  
  const fetchBusinesses = React.useCallback(async () => {
    setLoadingBusinesses(true);
    try {
      const response = await fetch(`${REACT_APP_API_BASE_URL}/businesses/get-all`);
      if (response.ok) {
        const data = await response.json();
        setBusinesses(data.businesses || []);
      }
    } catch (err) {
      setError('Failed to load businesses');
    } finally {
      setLoadingBusinesses(false);
    }
  }, [REACT_APP_API_BASE_URL]);

  useEffect(() => {
    if (isSignUp && userType === 'owner') {
      fetchBusinesses();
    }
  }, [isSignUp, userType, fetchBusinesses]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    setError('');
    setSuccess('');
  };

  const validateLoginForm = () => {
    if (!formData.email.trim()) {
      setError('Email is required');
      return false;
    }
    if (!formData.password.trim()) {
      setError('Password is required');
      return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      setError('Please enter a valid email address');
      return false;
    }
    return true;
  };

  const validateSignUpForm = () => {
    if (!formData.first_name.trim()) {
      setError('First name is required');
      return false;
    }
    if (!formData.last_name.trim()) {
      setError('Last name is required');
      return false;
    }
    if (!formData.email.trim()) {
      setError('Email is required');
      return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      setError('Please enter a valid email address');
      return false;
    }
    if (!formData.password.trim()) {
      setError('Password is required');
      return false;
    }
    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters');
      return false;
    }
    if (!formData.street.trim()) {
      setError('Street address is required');
      return false;
    }
    if (!formData.zip_code.trim()) {
      setError('ZIP code is required');
      return false;
    }
    if (!formData.city.trim()) {
      setError('City is required');
      return false;
    }
    if (!formData.country.trim()) {
      setError('Country is required');
      return false;
    }
    if (userType === 'owner' && !selectedBusinessId) {
      setError('Please select a business');
      return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (isSignUp) {
      if (!validateSignUpForm()) return;
    } else {
      if (!validateLoginForm()) return;
    }

    setLoading(true);

    try {
      if (isSignUp) {
        const signupData = {
          first_name: formData.first_name,
          last_name: formData.last_name,
          email: formData.email,
          phone: formData.phone || null,
          password: formData.password,
          user_type: userType, 
          business_id: userType === 'owner' ? selectedBusinessId : null, 
          address: {
            street: formData.street,
            building_number: formData.building_number || null,
            apartment_number: formData.apartment_number || null,
            zip_code: formData.zip_code,
            city: formData.city,
            state: formData.state || null,
            country: formData.country
          }
        };

        const response = await fetch(`${REACT_APP_API_BASE_URL}/auth/signup`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(signupData)
        });

        const data = await response.json();
        if (!response.ok) {
          throw new Error(data.error || 'Sign up failed');
        }

        setSuccess('Account created successfully! Logging in...');
        localStorage.setItem("currentUser", JSON.stringify(data.user));
        setTimeout(() => {
          onLoginSuccess(data.user);
        }, 1500);
      } else {
        const response = await fetch(`${REACT_APP_API_BASE_URL}/auth/login`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          credentials: 'include',
          body: JSON.stringify({
            email: formData.email,
            password: formData.password
          })
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.error || 'Login failed');
        }

        const data = await response.json();
        setSuccess('Login successful! Redirecting...');
                localStorage.setItem("currentUser", JSON.stringify(data.user));
        setTimeout(() => {
          onLoginSuccess(data.user);
        }, 1500);
      }
    } catch (err) {
      setError(err.message || 'An error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const toggleMode = () => {
    setIsSignUp(!isSignUp);
    setUserType(null);
    setSelectedBusinessId(null);
    setError('');
    setSuccess('');
    setFormData({
      email: '',
      password: '',
      first_name: '',
      last_name: '',
      phone: '',
      street: '',
      building_number: '',
      apartment_number: '',
      zip_code: '',
      city: '',
      state: '',
      country: ''
    });
  };
  if (isSignUp && !userType) {
    return (
      <div className={styles.authContainer}>
        <div className={styles.authBox}>
          <h1 className={styles.authTitle}>Create Account</h1>
          <p className={styles.authSubtitle}>Are you a customer or business owner?</p>

          {error && <div className={styles.errorMessage}>{error}</div>}

          <div className={styles.userTypeSelection}>
            <button
              className={`${styles.userTypeButton} ${styles.customer}`}
              onClick={() => setUserType('customer')}
            >
              <div className={styles.userTypeText}>
                <strong>Customer</strong>
                <p>Order from restaurants</p>
              </div>
            </button>

            <button
              className={`${styles.userTypeButton} ${styles.owner}`}
              onClick={() => setUserType('owner')}
            >
              <div className={styles.userTypeText}>
                <strong>Business Owner</strong>
                <p>Manage your restaurant</p>
              </div>
            </button>
          </div>

          <div className={styles.toggleMode}>
            <p>
              Already have an account?{' '}
              <button
                type="button"
                className={styles.toggleButton}
                onClick={toggleMode}
              >
                Log In
              </button>
            </p>
          </div>
        </div>
      </div>
    );
  }
  if (isSignUp && userType === 'owner' && !selectedBusinessId) {
    return (
      <div className={styles.authContainer}>
        <div className={styles.authBox}>
          <h1 className={styles.authTitle}>Select Your Business</h1>

          {error && <div className={styles.errorMessage}>{error}</div>}

          {loadingBusinesses ? (
            <div className={styles.loading}>Loading businesses...</div>
          ) : businesses.length === 0 ? (
            <div className={styles.noBusinesses}>
              <p>No businesses found. Please contact support.</p>
            </div>
          ) : (
            <div className={styles.businessSelection}>
              {businesses.map(business => (
                <button
                  key={business.id}
                  className={styles.businessCard}
                  onClick={() => setSelectedBusinessId(business.id)}
                >
                  <div className={styles.businessCardHeader}>
                    <h3>{business.name}</h3>
                  </div>
                  <div className={styles.businessCardInfo}>
                    <p className={styles.type}>{business.type}</p>
                    {business.phone && <p className={styles.phone}>{business.phone}</p>}
                  </div>
                </button>
              ))}
            </div>
          )}

          <button
            className={styles.backButton}
            onClick={() => {
              setUserType(null);
              setSelectedBusinessId(null);
            }}
          >
            ← Back
          </button>
        </div>
      </div>
    );
  }
  return (
    <div className={styles.authContainer}>
      <div className={styles.authBox}>
        <h1 className={styles.authTitle}>{isSignUp ? 'Sign Up' : 'Log In'}</h1>

        {isSignUp && userType === 'owner' && (
          <div className={styles.selectedBusiness}>
            Selected Business: <strong>{businesses.find(b => b.id === selectedBusinessId)?.name}</strong>
            <button
              className={styles.changeButton}
              onClick={() => setSelectedBusinessId(null)}
            >
              Change
            </button>
          </div>
        )}

        {error && <div className={styles.errorMessage}>{error}</div>}
        {success && <div className={styles.successMessage}>{success}</div>}

        <form onSubmit={handleSubmit} className={styles.authForm}>
          {!isSignUp ? (
            <>
              <div className={styles.formGroup}>
                <label htmlFor="email">Email</label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  placeholder="Enter your email"
                  disabled={loading}
                />
              </div>

              <div className={styles.formGroup}>
                <label htmlFor="password">Password</label>
                <input
                  type="password"
                  id="password"
                  name="password"
                  value={formData.password}
                  onChange={handleInputChange}
                  placeholder="Enter your password"
                  disabled={loading}
                />
              </div>
            </>
          ) : (
            <>
              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label htmlFor="first_name">First Name *</label>
                  <input
                    type="text"
                    id="first_name"
                    name="first_name"
                    value={formData.first_name}
                    onChange={handleInputChange}
                    placeholder="First name"
                    disabled={loading}
                  />
                </div>
                <div className={styles.formGroup}>
                  <label htmlFor="last_name">Last Name *</label>
                  <input
                    type="text"
                    id="last_name"
                    name="last_name"
                    value={formData.last_name}
                    onChange={handleInputChange}
                    placeholder="Last name"
                    disabled={loading}
                  />
                </div>
              </div>

              <div className={styles.formGroup}>
                <label htmlFor="email">Email *</label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  placeholder="your@email.com"
                  disabled={loading}
                />
              </div>

              <div className={styles.formGroup}>
                <label htmlFor="phone">Phone (Optional)</label>
                <input
                  type="tel"
                  id="phone"
                  name="phone"
                  value={formData.phone}
                  onChange={handleInputChange}
                  placeholder="+1 (555) 123-4567"
                  disabled={loading}
                />
              </div>

              <div className={styles.formGroup}>
                <label htmlFor="password">Password *</label>
                <input
                  type="password"
                  id="password"
                  name="password"
                  value={formData.password}
                  onChange={handleInputChange}
                  placeholder="At least 6 characters"
                  disabled={loading}
                />
              </div>

              <div className={styles.formDivider}>
                <span>Address Information</span>
              </div>

              <div className={styles.formGroup}>
                <label htmlFor="street">Street Address *</label>
                <input
                  type="text"
                  id="street"
                  name="street"
                  value={formData.street}
                  onChange={handleInputChange}
                  placeholder="123 Main Street"
                  disabled={loading}
                />
              </div>

              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label htmlFor="building_number">Building #</label>
                  <input
                    type="text"
                    id="building_number"
                    name="building_number"
                    value={formData.building_number}
                    onChange={handleInputChange}
                    placeholder="Building number"
                    disabled={loading}
                  />
                </div>
                <div className={styles.formGroup}>
                  <label htmlFor="apartment_number">Apt #</label>
                  <input
                    type="text"
                    id="apartment_number"
                    name="apartment_number"
                    value={formData.apartment_number}
                    onChange={handleInputChange}
                    placeholder="Apartment number"
                    disabled={loading}
                  />
                </div>
              </div>

              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label htmlFor="city">City *</label>
                  <input
                    type="text"
                    id="city"
                    name="city"
                    value={formData.city}
                    onChange={handleInputChange}
                    placeholder="City"
                    disabled={loading}
                  />
                </div>
                <div className={styles.formGroup}>
                  <label htmlFor="state">State</label>
                  <input
                    type="text"
                    id="state"
                    name="state"
                    value={formData.state}
                    onChange={handleInputChange}
                    placeholder="State"
                    disabled={loading}
                  />
                </div>
              </div>

              <div className={styles.formRow}>
                <div className={styles.formGroup}>
                  <label htmlFor="zip_code">ZIP Code *</label>
                  <input
                    type="text"
                    id="zip_code"
                    name="zip_code"
                    value={formData.zip_code}
                    onChange={handleInputChange}
                    placeholder="12345"
                    disabled={loading}
                  />
                </div>
                <div className={styles.formGroup}>
                  <label htmlFor="country">Country *</label>
                  <input
                    type="text"
                    id="country"
                    name="country"
                    value={formData.country}
                    onChange={handleInputChange}
                    placeholder="USA"
                    disabled={loading}
                  />
                </div>
              </div>
            </>
          )}

          <button
            type="submit"
            className={styles.submitButton}
            disabled={loading}
          >
            {loading ? 'Processing...' : (isSignUp ? 'Sign Up' : 'Log In')}
          </button>
        </form>

        <div className={styles.toggleMode}>
          <p>
            {isSignUp ? "Already have an account? " : "Don't have an account? "}
            <button
              type="button"
              className={styles.toggleButton}
              onClick={toggleMode}
            >
              {isSignUp ? 'Log In' : 'Sign Up'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;